import{_ as n,o as s,c as e,e as t}from"./app-6c9584fa.js";const i={};function p(l,a){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="_6-2-引入-code-interpreter-代码沙盒执行器-终结数据幻觉" tabindex="-1"><a class="header-anchor" href="#_6-2-引入-code-interpreter-代码沙盒执行器-终结数据幻觉" aria-hidden="true">#</a> 6.2 引入 Code Interpreter (代码沙盒执行器)，终结数据幻觉</h1><p>本节目标：把“让 LLM 口算/瞎猜”升级为“让 LLM 生成代码并在受控环境执行”，用可复核的计算结果替代“看似合理的自然语言结论”，并把执行过程纳入你现有的 BullMQ 异步任务与 WebSocket/SSE 实时回传体系。</p><hr><h2 id="_6-2-1-为什么必须做-code-interpreter-这是从-demo-到可用产品的分水岭" tabindex="-1"><a class="header-anchor" href="#_6-2-1-为什么必须做-code-interpreter-这是从-demo-到可用产品的分水岭" aria-hidden="true">#</a> 6.2.1 为什么必须做 Code Interpreter：这是从 Demo 到可用产品的分水岭</h2><p>在数据分析场景里，大模型的两类错误尤其致命：</p><ul><li>计算型幻觉：总和、占比、环比、分位数、异常点等一旦算错，所有结论都崩</li><li>口径型幻觉：维度粒度混乱（按月/按周）、单位混乱（元/万元）、重复/缺失处理不一致</li></ul><p>引入 Code Interpreter 的核心收益是：</p><ol><li>结果可复核：每个数字来自一段可运行代码（或一次 SQL 查询）</li><li>可重复：同样的输入与代码，产出一致</li><li>可审计：可以保存代码、输入数据、输出摘要、耗时、资源消耗</li><li>可治理：可以做超时、限流、配额、禁网、白名单依赖等安全控制</li></ol><hr><h2 id="_6-2-2-选择哪种执行形态-三种路线与推荐" tabindex="-1"><a class="header-anchor" href="#_6-2-2-选择哪种执行形态-三种路线与推荐" aria-hidden="true">#</a> 6.2.2 选择哪种执行形态：三种路线与推荐</h2><p>在 Node.js（NestJS）生态里常见有三种落地方式：</p><h3 id="路线-a-docker-隔离执行-推荐" tabindex="-1"><a class="header-anchor" href="#路线-a-docker-隔离执行-推荐" aria-hidden="true">#</a> 路线 A：Docker 隔离执行（推荐）</h3><p>特点：</p><ul><li>安全边界清晰：容器隔离 + 禁网 + 只读文件系统 + 资源限制</li><li>生态成熟：Python + pandas + duckdb + statsmodels 这些数据分析库都好用</li><li>可扩展：未来可以把执行器单独拆成微服务或 K8s Job</li></ul><p>代价：</p><ul><li>需要 Docker 运行时</li><li>冷启动会带来一点延迟（可通过镜像预热/长驻池化优化）</li></ul><h3 id="路线-b-wasm-执行-pyodide-webr-等" tabindex="-1"><a class="header-anchor" href="#路线-b-wasm-执行-pyodide-webr-等" aria-hidden="true">#</a> 路线 B：WASM 执行（Pyodide / WebR 等）</h3><p>特点：</p><ul><li>不依赖 Docker，部署简单</li><li>理论上更易做沙箱</li></ul><p>限制：</p><ul><li>生态与性能不如原生 Python</li><li>与 Node 服务的集成、包管理、文件 IO 相对复杂</li></ul><h3 id="路线-c-node-原生-vm-child-process-不推荐作为最终方案" tabindex="-1"><a class="header-anchor" href="#路线-c-node-原生-vm-child-process-不推荐作为最终方案" aria-hidden="true">#</a> 路线 C：Node 原生 VM/child_process（不推荐作为最终方案）</h3><p>特点：</p><ul><li>最好接入，最快跑通 Demo</li></ul><p>风险：</p><ul><li>很难做到强隔离（尤其是文件、网络、逃逸）</li><li>一旦做成产品，会在安全审计与多租户隔离上遇到大坑</li></ul><p>结论：本项目的最佳路线是 <strong>A（Docker 隔离执行）</strong>，并把执行放进 BullMQ Worker，避免阻塞 API。</p><hr><h2 id="_6-2-3-执行器的-安全模型-做产品必须具备的约束" tabindex="-1"><a class="header-anchor" href="#_6-2-3-执行器的-安全模型-做产品必须具备的约束" aria-hidden="true">#</a> 6.2.3 执行器的“安全模型”：做产品必须具备的约束</h2><p>无论你选择哪条路线，都建议把“安全约束”作为第一公民写进设计里：</p><h3 id="资源限制-必须" tabindex="-1"><a class="header-anchor" href="#资源限制-必须" aria-hidden="true">#</a> 资源限制（必须）</h3><ul><li>超时：例如 15s / 60s，按任务类型分级</li><li>内存：例如 512MB / 1GB</li><li>CPU：例如 0.5 / 1 core</li><li>输出大小：stdout、结果 JSON、图表数据都要限制最大字节数</li></ul><h3 id="能力限制-强烈建议" tabindex="-1"><a class="header-anchor" href="#能力限制-强烈建议" aria-hidden="true">#</a> 能力限制（强烈建议）</h3><ul><li>禁止外网：容器网络禁用，杜绝任意下载/回传</li><li>文件只读 + 临时目录：输入文件只读挂载，输出写到临时目录，任务结束销毁</li><li>依赖白名单：镜像内固定依赖版本，禁止 runtime pip install</li></ul><h3 id="数据与隐私-必须" tabindex="-1"><a class="header-anchor" href="#数据与隐私-必须" aria-hidden="true">#</a> 数据与隐私（必须）</h3><ul><li>输入数据脱敏策略：日志里不得打印原始数据全量</li><li>结果可追踪但可控：保存“摘要 + 哈希”，需要时再走权限去拉原始产物</li></ul><hr><h2 id="_6-2-4-agent-↔-执行器协议-一定要结构化-拒绝自由文本" tabindex="-1"><a class="header-anchor" href="#_6-2-4-agent-↔-执行器协议-一定要结构化-拒绝自由文本" aria-hidden="true">#</a> 6.2.4 Agent ↔ 执行器协议：一定要结构化，拒绝自由文本</h2><p>从 6.1 的多智能体骨架延续下来，Data Coder Agent 负责“生成执行计划”，执行器负责“按计划运行并返回结构化结果”。</p><p>建议定义一个统一的执行请求结构（并用 Zod 校验）：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">ExecLanguage</span> <span class="token operator">=</span> <span class="token string">&#39;python&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;sql&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">interface</span> <span class="token class-name">ExecRequest</span> <span class="token punctuation">{</span>
  language<span class="token operator">:</span> ExecLanguage<span class="token punctuation">;</span>
  code<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  inputs<span class="token operator">:</span> <span class="token punctuation">{</span>
    files<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">Array</span><span class="token operator">&lt;</span><span class="token punctuation">{</span> name<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> kind<span class="token operator">:</span> <span class="token string">&#39;csv&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;json&#39;</span><span class="token punctuation">;</span> ref<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
    params<span class="token operator">?</span><span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">unknown</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
  expected<span class="token operator">:</span> <span class="token punctuation">{</span>
    resultKeys<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>返回结构：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">interface</span> <span class="token class-name">ExecResponse</span> <span class="token punctuation">{</span>
  ok<span class="token operator">:</span> <span class="token builtin">boolean</span><span class="token punctuation">;</span>
  stdout<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  stderr<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  results<span class="token operator">?</span><span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">unknown</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
  artifacts<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">Array</span><span class="token operator">&lt;</span><span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&#39;plot&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;table&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;file&#39;</span><span class="token punctuation">;</span> name<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> ref<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
  metrics<span class="token operator">:</span> <span class="token punctuation">{</span> durationMs<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> cpuMs<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> memoryMb<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>设计要点：</p><ul><li><code>results</code> 必须是结构化 JSON（例如 tables、metrics、anomalies），而不是“把表格 print 出来”</li><li><code>artifacts</code> 用于返回图片或文件（例如导出的聚合 CSV、生成的 plot）</li><li><code>ref</code> 建议对接你在 Redis/DB 的 artifact 存储键（例如 <code>analysis:{id}:artifact:{name}</code>）</li></ul><hr><h2 id="_6-2-5-在-ai-data-analyzer-里怎么接-按步骤实现一条可用链路" tabindex="-1"><a class="header-anchor" href="#_6-2-5-在-ai-data-analyzer-里怎么接-按步骤实现一条可用链路" aria-hidden="true">#</a> 6.2.5 在 ai-data-analyzer 里怎么接：按步骤实现一条可用链路</h2><p>下面按“从小到大”的路径给出落地步骤，保证每一步都能验收。</p><h3 id="step-1-先把-执行器-当成一种工具-tool" tabindex="-1"><a class="header-anchor" href="#step-1-先把-执行器-当成一种工具-tool" aria-hidden="true">#</a> Step 1：先把“执行器”当成一种工具（Tool）</h3><p>在 6.1 的工具体系里新增一个工具：</p><ul><li><code>run_python</code>：输入 <code>ExecRequest</code>，输出 <code>ExecResponse</code></li></ul><p>这一步的目标是：先跑通“LLM 生成代码 -&gt; 执行 -&gt; 回传结构化结果”的闭环。</p><h3 id="step-2-执行器服务化-bullmq-worker-化" tabindex="-1"><a class="header-anchor" href="#step-2-执行器服务化-bullmq-worker-化" aria-hidden="true">#</a> Step 2：执行器服务化 + BullMQ Worker 化</h3><p>建议将执行器放入 Worker（避免阻塞 API），并为其单独建立队列：</p><ul><li><code>code-exec</code> 队列：专门执行代码沙盒任务</li></ul><p>执行流程：</p><ol><li>Supervisor / Data Coder 生成 <code>ExecRequest</code></li><li>入队 <code>code-exec</code></li><li>Worker 拉取任务 -&gt; 调起 Docker 容器执行 -&gt; 产出 <code>ExecResponse</code></li><li>写入 artifacts（Redis/DB/对象存储）并推送 WebSocket 状态</li></ol><h3 id="step-3-结果回传与前端展示策略" tabindex="-1"><a class="header-anchor" href="#step-3-结果回传与前端展示策略" aria-hidden="true">#</a> Step 3：结果回传与前端展示策略</h3><p>建议把回传分成三类：</p><ul><li>进度事件（WebSocket）：<code>started / running / finished / failed</code></li><li>可读输出（SSE）：stdout 的“节选”或逐行流式输出（注意截断）</li><li>结构化产物（HTTP 拉取）：图表数据、聚合表、异常点列表，按 artifact ref 获取</li></ul><p>前端体验上，用户会明显感觉“AI 在做事”，而不是“等待一次性回答”。</p><h3 id="step-4-把-data-coder-从-口算-升级为-默认写代码" tabindex="-1"><a class="header-anchor" href="#step-4-把-data-coder-从-口算-升级为-默认写代码" aria-hidden="true">#</a> Step 4：把 Data Coder 从“口算”升级为“默认写代码”</h3><p>策略建议：</p><ul><li>对所有涉及聚合/统计/排序/异常检测的任务，强制走执行器</li><li>只有纯文本总结、业务解释可以不走执行器</li></ul><p>这样做能显著降低幻觉率，也能为 6.5 的“Token/成本账本”提供可解释的成本构成（LLM Tokens + Exec 耗时）。</p><hr><h2 id="_6-2-6-典型任务模板-让-agent-更稳定的关键" tabindex="-1"><a class="header-anchor" href="#_6-2-6-典型任务模板-让-agent-更稳定的关键" aria-hidden="true">#</a> 6.2.6 典型任务模板：让 Agent 更稳定的关键</h2><p>为了稳定产出，建议给 Data Coder 提供“任务模板”而不是让它自由写：</p><h3 id="a-数据剖析-profile" tabindex="-1"><a class="header-anchor" href="#a-数据剖析-profile" aria-hidden="true">#</a> A. 数据剖析（Profile）</h3><p>输入：CSV / JSON 表</p><p>输出（结构化）：</p><ul><li>字段类型推断（数值/类别/时间）</li><li>缺失率、重复率</li><li>数值字段的 min/max/mean/quantiles</li><li>类别字段 topK</li></ul><h3 id="b-指标计算-metrics" tabindex="-1"><a class="header-anchor" href="#b-指标计算-metrics" aria-hidden="true">#</a> B. 指标计算（Metrics）</h3><p>输入：维度字段、度量字段、窗口（按月/按周）</p><p>输出（结构化）：</p><ul><li>聚合表</li><li>指标表（环比、同比、占比、贡献度）</li></ul><h3 id="c-异常检测-anomaly" tabindex="-1"><a class="header-anchor" href="#c-异常检测-anomaly" aria-hidden="true">#</a> C. 异常检测（Anomaly）</h3><p>输入：时间序列或分布</p><p>输出（结构化）：</p><ul><li>异常点列表 + 异常原因（规则解释）</li><li>置信度与阈值（便于审阅）</li></ul><p>这些模板会让 Reviewer 更容易做一致性审计。</p><hr><h2 id="_6-2-7-风险与工程细节-提前避免返工" tabindex="-1"><a class="header-anchor" href="#_6-2-7-风险与工程细节-提前避免返工" aria-hidden="true">#</a> 6.2.7 风险与工程细节：提前避免返工</h2><ul><li>结果 JSON 的大小控制：大表不要直接塞进 <code>results</code>，只返回摘要 + artifact ref</li><li>版本可重复：镜像版本要固定，否则同样代码在不同环境可能输出不同</li><li>代码注入与逃逸：不要让执行器拥有任何外网、凭证、主机读写权限</li><li>任务隔离：多租户时必须按 workspace 隔离 artifact key（6.4 章会接上）</li></ul><hr><h2 id="_6-2-8-验收标准-做到这一步-幻觉率会明显下降" tabindex="-1"><a class="header-anchor" href="#_6-2-8-验收标准-做到这一步-幻觉率会明显下降" aria-hidden="true">#</a> 6.2.8 验收标准：做到这一步，幻觉率会明显下降</h2><ul><li>对任意 CSV，能稳定生成一份 profile 结构化输出（缺失率/类型/基本统计）</li><li>对任意“求和、最大值、分组聚合”的问题，默认走执行器并返回可复核结果</li><li>前端能看到执行进度与关键产物（表/图/异常列表）</li><li>执行器具备基础安全约束：超时、输出限制、禁网（至少三项到位）</li></ul>`,87)])])}const r=n(i,[["render",p],["__file","6.2 引入 Code Interpreter 终结数据幻觉.html.vue"]]);export{r as default};
